-- ============================================================
-- Lacerating Shot needs a family flag to be modifiable
-- ============================================================
--
-- Same trap as Instinctive Fire's buff, one talent along: without this the
-- +2/4/6 sec above silently does NOTHING and nothing logs.
-- Player::IsAffectedBySpellMod requires `spellmod->mask & spellInfo->
-- SpellFamilyFlags` to be non-zero, and Lacerating Shot's three ranks were left
-- with SpellFamilyName 9 but all three flag words zero after their rework.
--
-- That zeroing is why spell_hun_taste_for_blood and
-- spell_hun_piercing_shots_lacerate both have to name the ranks explicitly
-- instead of matching a family mask.  Those scripts are unaffected by this
-- change -- they look the spell up by id -- so the bit is purely for the
-- modifier's benefit.
--
-- Bit 23 of word 2 (8388608).  Bits 21 and 22 are already taken by Instinctive
-- Fire and its buff; 23 was verified free by scanning every family-9 record in
-- Spell.dbc, as neither a flag nor a mask.  All three ranks share one bit, which
-- is how a rank chain normally works and what lets one mask cover all of them.
--
-- UPDATE, not a re-INSERT: the full rows live in woa_2026_08_11_02.sql, which
-- sorts earlier, so these land on top of them.

UPDATE `alonecraft_spell_dbc` SET `SpellFamilyFlags2` = 8388608 WHERE `ID` IN (1513, 14326, 14327);

-- ============================================================
-- Piercing Shots: proc chance, and the second script
-- ============================================================
--
-- THE Chance = 100 HERE IS THE WHOLE POINT OF THIS BLOCK.  Core's row ships
-- Chance = 0, which makes Aura::CalcProcChance fall back to the DBC ProcChance
-- (SpellMgr.cpp:2083).  Since the DBC ProcChance above is now 33/66/100 -- it
-- has to be, because $h in the description reads it -- leaving the row at 0
-- would silently drop the BLEED to a 33% chance at rank 1.  The two numbers are
-- deliberately different things: the bleed always happens, the refresh is the
-- part that rolls.
--
-- Everything else on the row is core's, restated so the whole thing is visible
-- in one place: family 9, masks 131072/1/1 (Aimed / Steady / Chimera),
-- SpellPhaseMask 2, HitMask 2 (PROC_HIT_CRITICAL).

DELETE FROM `spell_proc` WHERE `SpellId` = -53234;
INSERT INTO `spell_proc` (`SpellId`, `SchoolMask`, `SpellFamilyName`, `SpellFamilyMask0`, `SpellFamilyMask1`, `SpellFamilyMask2`, `ProcFlags`, `SpellTypeMask`, `SpellPhaseMask`, `HitMask`, `AttributesMask`, `DisableEffectsMask`, `ProcsPerMinute`, `Chance`, `Cooldown`, `Charges`) VALUES
(-53234, 0, 9, 131072, 1, 1, 0, 0, 2, 2, 0, 0, 0, 100, 0, 0);

-- ADDED ALONGSIDE core's spell_hun_piercing_shots, not instead of it.  The
-- bleed is already correct in core (spell_hunter.cpp:1622) and only its
-- percentage changed, which is the DBC edit above.
--
-- _spellScriptsStore is a multimap (ObjectMgr.h:390) and
-- Aura::CallScriptEffectProcHandlers iterates every loaded script
-- (SpellAuras.cpp:2723), so both run.  The new script therefore must NOT
-- register DoCheckProc and must NOT call PreventDefaultAction:
-- CallScriptCheckProcHandlers ANDs results across scripts (SpellAuras.cpp:2625)
-- and prevention is global, so either one would silently kill core's bleed.

DELETE FROM `spell_script_names` WHERE `spell_id` = -53234 AND `ScriptName` = 'spell_hun_piercing_shots_lacerate';
INSERT INTO `spell_script_names` (`spell_id`, `ScriptName`) VALUES
(-53234, 'spell_hun_piercing_shots_lacerate');
